SELECT CASE WHEN duration_sec >= 477 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, event_type, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT(*) FILTER (WHERE event_type = 'page_view') AS page_view_rows, SUM(duration_sec) FILTER (WHERE event_type = 'search') AS search_total_duration_sec, PERCENTILE_APPROX(duration_sec, 0.95) AS duration_sec_p95, COUNT(*) AS num_rows, STDDEV_SAMP(duration_sec) AS duration_sec_stddev FROM web_events GROUP BY CASE WHEN duration_sec >= 477 THEN 'HIGH' ELSE 'LOW' END, event_type ORDER BY event_type DESC
